import{_ as a,o as e,c as i,a3 as t}from"./chunks/framework.vDgOMd_y.js";const g=JSON.parse('{"title":"Goals","description":"","frontmatter":{},"headers":[],"relativePath":"en/guides/goals.md","filePath":"en/guides/goals.md"}'),n={name:"en/guides/goals.md"};function l(h,s,o,p,d,r){return e(),i("div",null,[...s[0]||(s[0]=[t('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/guides/goals.md for this page in Markdown format</div><h1 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h1><p>Goals keep Kimi Code working toward a defined outcome across turns. Unlike a normal prompt that says what to do next, a goal says what must become true. Use <code>/goal</code> when the task has a clear finish line, but the next useful step depends on what the agent learns while it works — for example, fixing a batch of failing tests or tracking down the root cause of a broken build.</p><h2 id="start-a-goal" tabindex="-1">Start a goal <a class="header-anchor" href="#start-a-goal" aria-label="Permalink to &quot;Start a goal&quot;">​</a></h2><p>Write the objective after <code>/goal</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Fix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bugs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> listed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> issue</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tracker.</span></span></code></pre></div><p>Kimi Code saves the objective, sends it as the next user message, and starts goal mode. After each turn, it checks whether the goal is complete, blocked, paused, or still active.</p><p>Goals work best when the objective names the finish line and the evidence that proves it:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Fix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> every</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bug</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> labeled</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout-regression,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> or</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> for</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> each</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fix,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> suite</span></span></code></pre></div><p>Avoid goals that only name a broad direction:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bugs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> this</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codebase.</span></span></code></pre></div><p>That goal does not say what counts as success, what to inspect, or when to stop. The agent may block immediately, or keep working far longer than you expected.</p><h3 id="when-to-use-goals" tabindex="-1">When to use goals <a class="header-anchor" href="#when-to-use-goals" aria-label="Permalink to &quot;When to use goals&quot;">​</a></h3><ol><li><p>Use goals for work with a clear finish line and verifiable evidence.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Fix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> every</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> failing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> successfully.</span></span></code></pre></div><p>Kimi Code can inspect test output, change files, rerun checks, and decide when the goal is complete.</p></li><li><p>Use goals when the task may need several turns of investigation and repair.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> why</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fails,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cause,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> passes.</span></span></code></pre></div><p>The goal describes the result, so the agent can adapt when the first clue is not the root cause.</p></li><li><p>Use goals for ordered work that should continue without another prompt.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> implementation,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> summarize</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> changed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> files.</span></span></code></pre></div><p>This is useful when you already know the checks or artifacts that must exist before the work is done.</p></li></ol><h3 id="when-not-to-use-goals" tabindex="-1">When not to use goals <a class="header-anchor" href="#when-not-to-use-goals" aria-label="Permalink to &quot;When not to use goals&quot;">​</a></h3><ol><li><p>Do not use goals for broad topics or open-ended discussions.</p><div class="warning custom-block"><p class="custom-block-title">Counterexample</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Greetings!</span></span></code></pre></div></div><p>Agents will mark the goal as complete immediately for non-goals.</p></li><li><p>Do not use goals for tasks that are known to be impossible or unresolvable.</p><div class="warning custom-block"><p class="custom-block-title">Counterexample</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Prove</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3.</span></span></code></pre></div></div><p>Agents will mark the goal as blocked if the goal seems impossible or unresolvable.</p></li><li><p>Do not use goals with ambiguous or complicated objectives.</p><div class="warning custom-block"><p class="custom-block-title">Counterexample</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> videogame</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> single</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HTML</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file.</span></span></code></pre></div></div><p>Agents may complete goals, but also may produce unexpected or surprising outcomes after a long time.</p></li></ol><h2 id="manage-the-lifecycle" tabindex="-1">Manage the lifecycle <a class="header-anchor" href="#manage-the-lifecycle" aria-label="Permalink to &quot;Manage the lifecycle&quot;">​</a></h2><p>Use the same command surface to inspect or control the current goal:</p><table tabindex="0"><thead><tr><th>Command</th><th>Action</th></tr></thead><tbody><tr><td><code>/goal</code> or <code>/goal status</code></td><td>Show the current goal and its progress</td></tr><tr><td><code>/goal pause</code></td><td>Pause the active goal without deleting it</td></tr><tr><td><code>/goal resume</code></td><td>Resume a paused or blocked goal</td></tr><tr><td><code>/goal cancel</code></td><td>Remove the current goal</td></tr><tr><td><code>/goal replace &lt;objective&gt;</code></td><td>Replace the current goal with a new objective</td></tr></tbody></table><p>A goal can stop in three ways:</p><ul><li><strong>complete</strong>: the objective is done, Kimi Code clears the goal, and the agent summarizes how it completed the work</li><li><strong>paused</strong>: you paused it, interrupted the turn, resumed a session that had an active goal, or hit a model, provider, or runtime error</li><li><strong>blocked</strong>: Kimi Code needs input, cannot complete the goal as stated, or reached a budget limit. When the agent blocks a goal, it writes a short message explaining why.</li></ul><p>Write stop conditions into the objective. <code>/goal</code> does not have a separate stop-limit flag.</p><h2 id="manage-goals-in-the-web-ui" tabindex="-1">Manage goals in the web UI <a class="header-anchor" href="#manage-goals-in-the-web-ui" aria-label="Permalink to &quot;Manage goals in the web UI&quot;">​</a></h2><p>The web UI shows the current goal in a strip below the conversation. Select the strip to expand or collapse its details. When a token budget is configured, the header shows its progress; goals without a token budget do not show a progress bar.</p><p>Use the strip actions to pause an active goal, resume a paused or blocked goal, or cancel the current goal. Selecting Resume starts the next goal turn so the agent continues the work. Cancellation requires confirmation because it cannot be resumed afterwards.</p><h2 id="queue-upcoming-goals" tabindex="-1">Queue upcoming goals <a class="header-anchor" href="#queue-upcoming-goals" aria-label="Permalink to &quot;Queue upcoming goals&quot;">​</a></h2><p>Agents sometimes complete a goal too quickly. Users can be disappointed that they can assign only one goal at a time. Many people already know the upcoming goals they want to pursue. They had to wait for the current goal to complete, open the TUI, and submit the next goal manually.</p><p>Use <code>/goal next</code> when you have more work ready but do not want to interrupt the current goal:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> next</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notes</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> after</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pass</span></span></code></pre></div><p>Upcoming goals are not visible to the agent while the current goal is running. When the current goal completes, Kimi Code starts the first upcoming goal in the same way as users enter <code>/goal &lt;objective&gt;</code>.</p><p>If no goal is active, <code>/goal next &lt;objective&gt;</code> starts that objective immediately. It behaves like <code>/goal &lt;objective&gt;</code> and shows a status message before the goal starts.</p><p>Manage upcoming goals interactively:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/goal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> next</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage</span></span></code></pre></div><p>In the manager, use <kbd>↑</kbd> / <kbd>↓</kbd> to browse, <kbd>Space</kbd> to select a goal for moving, <kbd>↑</kbd> / <kbd>↓</kbd> to reorder it, <kbd>E</kbd> to edit, <kbd>D</kbd> to delete, and <kbd>Esc</kbd> to cancel. When editing, use <kbd>Shift-Enter</kbd> or <kbd>Ctrl-J</kbd> to add a new line, and <kbd>Enter</kbd> to save.</p><p>If the current goal is paused, canceled, or blocked, Kimi Code does not start the next upcoming goal. When a goal blocks and upcoming goals exist, the TUI reminds you that they wait for completion.</p><h2 id="use-goal-mode-carefully" tabindex="-1">Use goal mode carefully <a class="header-anchor" href="#use-goal-mode-carefully" aria-label="Permalink to &quot;Use goal mode carefully&quot;">​</a></h2><p>Goal mode is useful for work that can be checked with files, tests, command output, generated artifacts, or a clear written report. It is less useful for a one-off edit or a question that only needs one answer.</p><p>In <code>manual</code> permission mode, goal work may pause for tool call approval. For unattended work, use a permission mode that matches the risk of the repository and the commands the agent may run.</p><p>In non-interactive prompt mode, only goal creation is supported:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/goal Fix the failing checkout test&quot;</span></span></code></pre></div><p>Prompt mode exits with code <code>0</code> when the goal completes, <code>3</code> when it blocks, and <code>6</code> when it pauses. <code>/goal next</code> and other management commands are TUI controls.</p>',41)])])}const c=a(n,[["render",l]]);export{g as __pageData,c as default};
